<script setup lang="ts">
import { onMounted,onBeforeUnmount,ref,watch } from 'vue'
import InformationRequestThread from './InformationRequestThread.vue'
const emit=defineEmits<{processing:[value:boolean]}>()
const props=defineProps<{employeeId?:number}>()
const items=ref<any[]>([]),pagination=ref({page:1,pages:1,total:0}),status=ref('Pending'),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),opened=ref<number|null>(null),reply=ref(''),nextStatus=ref('In review'),review=ref<any>(null)
let owner=0,controller:AbortController|null=null
watch(busy,value=>emit('processing',value))
async function load(page=1){const current=++owner;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result:any=await $fetch('/api/payroll/payslips/requests',{query:{employeeId:props.employeeId,status:status.value||undefined,search:search.value.trim(),page},signal:controller.signal,retry:0,timeout:15000});if(current===owner){items.value=result.items;pagination.value=result.pagination}}catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to load information requests.'}finally{if(current===owner)loading.value=false}}
function open(item:any){opened.value=opened.value===item.RequestID?null:item.RequestID;reply.value='';nextStatus.value=item.Status==='Pending'?'In review':item.Status;review.value=null}
function prepare(item:any){review.value={requestId:item.RequestID,version:item.Version,message:reply.value.trim(),status:nextStatus.value}}
async function send(){if(!review.value||busy.value)return;const body={...review.value},current=owner;busy.value=true;error.value='';notice.value='';try{await $fetch('/api/payroll/payslips/requests',{method:'POST',body,retry:0,timeout:20000});if(current!==owner)return;review.value=null;notice.value='Reply and request status saved. The employee record was not changed.';await load(pagination.value.page)}catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to send this reply. Reload if the request changed.'}finally{busy.value=false}}
onMounted(()=>void load());watch(()=>props.employeeId,()=>{opened.value=null;review.value=null;void load()});onBeforeUnmount(()=>{owner++;controller?.abort();emit('processing',false)})
</script>
<template><section class="admin-requests"><header><p class="eyebrow">HR / PAYROLL INBOX</p><h3>Employee information requests</h3><p>Review corrections, reply to the employee, and track the outcome. Update approved information through Employee Management before marking a request Resolved.</p></header><form class="filters" @submit.prevent="load()"><label>Search employee or information<input v-model="search" type="search" placeholder="Name, employee number, or field"></label><label>Request status<select v-model="status"><option value="">All statuses</option><option>Pending</option><option>In review</option><option>Resolved</option><option>Declined</option><option>Cancelled</option></select></label><button type="submit" :disabled="loading||busy">Search</button></form><p v-if="error" class="error" role="alert">{{error}} <button type="button" :disabled="busy" @click="load()">Reload</button></p><p v-if="notice" class="success" role="status">{{notice}}</p><small>{{pagination.total}} requests</small><div class="request-list"><article v-for="item in items" :key="item.RequestID"><button type="button" class="row" :disabled="busy" @click="open(item)"><span><strong>{{item.EmployeeName}}</strong><small>{{item.EmployeeNumber}} &middot; {{item.AgencyName}}</small></span><span>{{item.FieldLabel}}<small>#{{item.RequestID}} &middot; {{item.Status}}</small></span></button><div v-if="opened===item.RequestID" class="detail"><InformationRequestThread :request="item" viewer="staff"/><form v-if="item.Status!=='Cancelled'&&!review" class="reply-form" @submit.prevent="prepare(item)"><label>Reply to employee<textarea v-model="reply" required maxlength="2000" rows="3" placeholder="Explain what was reviewed, what was corrected, or what HR still needs."></textarea></label><label>Set request status<select v-model="nextStatus" required><option>In review</option><option>Resolved</option><option>Declined</option></select></label><small>This action records a reply and status only. It does not edit the employee record.</small><button type="submit" :disabled="busy">Review response</button></form><div v-else-if="review" class="review"><h4>Confirm reply &amp; status</h4><p>{{review.message}}</p><p>Status: <strong>{{review.status}}</strong></p><div><button type="button" :disabled="busy" @click="review=null">Keep editing</button><button type="button" class="primary" :disabled="busy" @click="send">{{busy?'Saving...':'Confirm and send'}}</button></div></div></div></article><p v-if="!items.length" class="empty">{{loading?'Loading requests...':'No requests match your filters.'}}</p></div><div class="pages"><button type="button" :disabled="busy||loading||pagination.page<=1" @click="load(pagination.page-1)">Previous</button><small>{{pagination.page}} / {{pagination.pages}}</small><button type="button" :disabled="busy||loading||pagination.page>=pagination.pages" @click="load(pagination.page+1)">Next</button></div></section></template>
<style scoped>
.admin-requests{font:inherit;color:#1e385c;min-width:0}.admin-requests *{box-sizing:border-box}h3{font-size:1.25rem;margin:7px 0 10px}.eyebrow{font-size:.65rem;font-weight:800;letter-spacing:.09em;color:#2d64cc;margin:0}header>p:not(.eyebrow){font-size:.82rem;color:#647e9e;line-height:1.8;max-width:800px}button{min-height:40px;padding:10px 13px;border:1px solid #cbd9ed;border-radius:8px;background:#fff;color:#2d5da1;font:inherit;font-size:.77rem;font-weight:700;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:#2863d9;color:#fff}.filters{display:grid;grid-template-columns:minmax(0,1fr) 190px auto;gap:12px;align-items:end;margin:22px 0}label{display:grid;gap:7px;font-size:.76rem;color:#4d678b;font-weight:700}input,select,textarea{width:100%;min-width:0;max-width:100%;padding:10px 12px;border:1px solid #cbd8eb;border-radius:8px;background:#fff;color:#18375f;font:inherit;font-size:.86rem}.request-list{display:grid;gap:14px;margin-top:16px}.request-list>article{border:1px solid #d9e3f1;border-radius:11px;background:#fff;overflow:hidden}.row{display:flex;justify-content:space-between;gap:20px;align-items:center;width:100%;border:0;border-radius:0;text-align:left;padding:18px}.row>span{min-width:0;overflow-wrap:anywhere}.row strong{display:block;font-size:.86rem}.row small,small{display:block;color:#6d819e;font-size:.7rem;font-weight:400;line-height:1.8;margin-top:4px}.detail{border-top:1px solid #e1e9f3;padding:20px}.reply-form{display:grid;gap:14px;margin-top:20px}.reply-form button{justify-self:start}.review{padding:20px;background:#f1f6ff;border-radius:9px;margin-top:18px}.review h4{margin:0}.review p{font-size:.85rem;white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}.review>div,.pages{display:flex;gap:10px;align-items:center}.pages{justify-content:flex-end;margin-top:18px}.error,.success{padding:13px;border-radius:8px;font-size:.82rem;line-height:1.7;background:#fff0f0;color:#a32f3c}.success{background:#eaf8ef;color:#246e4a}.empty{padding:30px;text-align:center;color:#6b819d;font-size:.83rem}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #adc9f5;outline-offset:2px}@media(max-width:700px){.filters{grid-template-columns:1fr}.row{align-items:flex-start;flex-direction:column;gap:9px}.detail{padding:17px}input,select,textarea{font-size:16px}}
</style>
